// A. Conceptual ERD (Mermaid erDiagram) — entities, identifiers, verb-labelled relationships, crow's-foot cardinality, NO foreign keys.
const ERD = `
erDiagram
  PATIENT ||--o{ APPOINTMENT : books
  PATIENT {
    string patientId PK
  }
  APPOINTMENT {
    string appointmentCode PK
  }
`;

// B. State diagram of an Appointment (Mermaid stateDiagram-v2): event [guard] / action.
