// A. Nine entities; APPOINTMENT links patient, slot and service; PRESCRIPTION_ITEM carries the dosage.
const ERD = `
erDiagram
  PATIENT ||--o{ APPOINTMENT : books
  DOCTOR ||--o{ TIME_SLOT : publishes
  TIME_SLOT ||--o| APPOINTMENT : "is reserved by"
  SERVICE ||--o{ APPOINTMENT : "is requested in"
  APPOINTMENT ||--o{ PAYMENT : "is paid by"
  APPOINTMENT ||--o| PRESCRIPTION : "results in"
  PRESCRIPTION ||--|{ PRESCRIPTION_ITEM : contains
  MEDICINE ||--o{ PRESCRIPTION_ITEM : "is prescribed in"
  PATIENT {
    string patientId PK
    string fullName
    string phone
    date dateOfBirth
  }
  DOCTOR {
    string doctorId PK
    string fullName
    string specialty
  }
  TIME_SLOT {
    string slotId PK
    datetime startTime
    int minutes
  }
  SERVICE {
    string serviceCode PK
    string name
    decimal fee
  }
  APPOINTMENT {
    string appointmentCode PK
    string status
    datetime bookedAt
  }
  PAYMENT {
    string paymentId PK
    decimal amount
    string kind
    datetime paidAt
  }
  PRESCRIPTION {
    string prescriptionId PK
    string nationalCode
    date issuedOn
  }
  PRESCRIPTION_ITEM {
    int lineNo PK
    string dosage
    int quantity
  }
  MEDICINE {
    string medicineId PK
    string name
    string unit
  }
`;
